diff --git a/scripts/generate-favicons.js b/scripts/generate-favicons.js
new file mode 100644
index 0000000..ea58366
--- /dev/null
+++ b/scripts/generate-favicons.js
@@ -0,0 +1,165 @@
+const sharp = require('sharp');
+const fs = require('fs');
+const path = require('path');
+
+// SVG source for the favicon - RT Monogram (stylized intertwined calligraphic R and T)
+const svgSource = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">
+  <rect width="32" height="32" rx="4" ry="4" fill="#FF1493"/>
+  <g fill="none" stroke="#FFFFFF" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
+    <path d="M10 8 C10 5 12 4 14 5 C16 6 16 8 14 10 C12 12 10 12 10 12 L10 26"/>
+    <path d="M11 14 Q14 19 16 26"/>
+    <path d="M5 10 Q16 9 26 10"/>
+    <path d="M20 10 L20 26"/>
+  </g>
+</svg>`;
+
+// Higher resolution SVG for better quality at larger sizes (180x180)
+const svgSourceHiRes = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 180 180">
+  <rect width="180" height="180" rx="22" ry="22" fill="#FF1493"/>
+  <g fill="none" stroke="#FFFFFF" stroke-width="10" stroke-linecap="round" stroke-linejoin="round">
+    <path d="M56 45 C56 28 68 22 79 28 C90 34 90 45 79 56 C68 67 56 67 56 67 L56 146"/>
+    <path d="M62 79 Q79 107 90 146"/>
+    <path d="M28 56 Q90 51 146 56"/>
+    <path d="M113 56 L113 146"/>
+  </g>
+</svg>`;
+
+const outputDir = path.join(__dirname, '..', 'src');
+
+async function generateFavicons() {
+  console.log('Generating favicons...');
+
+  // Generate apple-touch-icon.png (180x180)
+  await sharp(Buffer.from(svgSourceHiRes))
+    .resize(180, 180)
+    .png()
+    .toFile(path.join(outputDir, 'apple-touch-icon.png'));
+  console.log('Created apple-touch-icon.png (180x180)');
+
+  // Generate favicon-32x32.png
+  await sharp(Buffer.from(svgSource))
+    .resize(32, 32)
+    .png()
+    .toFile(path.join(outputDir, 'favicon-32x32.png'));
+  console.log('Created favicon-32x32.png');
+
+  // Generate favicon-16x16.png
+  await sharp(Buffer.from(svgSource))
+    .resize(16, 16)
+    .png()
+    .toFile(path.join(outputDir, 'favicon-16x16.png'));
+  console.log('Created favicon-16x16.png');
+
+  // Generate ICO file (contains both 16x16 and 32x32)
+  // ICO format: header + entries + image data
+  const png16 = await sharp(Buffer.from(svgSource))
+    .resize(16, 16)
+    .png()
+    .toBuffer();
+
+  const png32 = await sharp(Buffer.from(svgSource))
+    .resize(32, 32)
+    .png()
+    .toBuffer();
+
+  const icoBuffer = createIco([
+    { size: 16, data: png16 },
+    { size: 32, data: png32 }
+  ]);
+
+  fs.writeFileSync(path.join(outputDir, 'favicon.ico'), icoBuffer);
+  console.log('Created favicon.ico');
+
+  // Create site.webmanifest
+  const webmanifest = {
+    "name": "Rita Tomforde",
+    "short_name": "RT",
+    "icons": [
+      {
+        "src": "/favicon-32x32.png",
+        "sizes": "32x32",
+        "type": "image/png"
+      },
+      {
+        "src": "/apple-touch-icon.png",
+        "sizes": "180x180",
+        "type": "image/png"
+      }
+    ],
+    "theme_color": "#FF1493",
+    "background_color": "#FFFBF9",
+    "display": "standalone"
+  };
+
+  fs.writeFileSync(
+    path.join(outputDir, 'site.webmanifest'),
+    JSON.stringify(webmanifest, null, 2)
+  );
+  console.log('Created site.webmanifest');
+
+  console.log('All favicons generated successfully!');
+}
+
+// Create ICO file from PNG images
+function createIco(images) {
+  // ICO file format:
+  // - ICONDIR header (6 bytes)
+  // - ICONDIRENTRY for each image (16 bytes each)
+  // - Image data (PNG format)
+
+  const headerSize = 6;
+  const entrySize = 16;
+  const numImages = images.length;
+
+  // Calculate total size
+  let totalSize = headerSize + (entrySize * numImages);
+  for (const img of images) {
+    totalSize += img.data.length;
+  }
+
+  const buffer = Buffer.alloc(totalSize);
+  let offset = 0;
+
+  // ICONDIR header
+  buffer.writeUInt16LE(0, offset);      // Reserved (must be 0)
+  offset += 2;
+  buffer.writeUInt16LE(1, offset);      // Image type: 1 = ICO
+  offset += 2;
+  buffer.writeUInt16LE(numImages, offset);  // Number of images
+  offset += 2;
+
+  // Calculate data offsets
+  let dataOffset = headerSize + (entrySize * numImages);
+
+  // ICONDIRENTRY for each image
+  for (const img of images) {
+    buffer.writeUInt8(img.size === 256 ? 0 : img.size, offset);  // Width (0 = 256)
+    offset += 1;
+    buffer.writeUInt8(img.size === 256 ? 0 : img.size, offset);  // Height (0 = 256)
+    offset += 1;
+    buffer.writeUInt8(0, offset);       // Color palette (0 = no palette)
+    offset += 1;
+    buffer.writeUInt8(0, offset);       // Reserved
+    offset += 1;
+    buffer.writeUInt16LE(1, offset);    // Color planes
+    offset += 2;
+    buffer.writeUInt16LE(32, offset);   // Bits per pixel
+    offset += 2;
+    buffer.writeUInt32LE(img.data.length, offset);  // Image size
+    offset += 4;
+    buffer.writeUInt32LE(dataOffset, offset);       // Image offset
+    offset += 4;
+
+    dataOffset += img.data.length;
+  }
+
+  // Write image data
+  for (const img of images) {
+    img.data.copy(buffer, offset);
+    offset += img.data.length;
+  }
+
+  return buffer;
+}
+
+generateFavicons().catch(console.error);

diff --git a/_site/css/modules/print.css b/_site/css/modules/print.css
new file mode 100644
index 0000000..c827614
--- /dev/null
+++ b/_site/css/modules/print.css
@@ -0,0 +1,249 @@
+/* ==========================================================================
+   Print Module
+   Optimized print styles for portfolio website
+   Provides clean, readable output for printing painting information and contact details
+   ========================================================================== */
+
+@media print {
+    /* ==========================================================================
+       General Print Optimizations
+       ========================================================================== */
+
+    * {
+        background: transparent !important;
+        color: #000 !important;
+        box-shadow: none !important;
+        text-shadow: none !important;
+    }
+
+    body {
+        font-size: 12pt;
+        line-height: 1.5;
+        color: #000;
+        background: #fff;
+    }
+
+    /* ==========================================================================
+       Page Layout
+       ========================================================================== */
+
+    @page {
+        margin: 2cm;
+        size: auto;
+    }
+
+    /* Remove unnecessary spacing */
+    .container,
+    .footer-container {
+        width: 100%;
+        max-width: none;
+        padding: 0;
+        margin: 0;
+    }
+
+    /* ==========================================================================
+       Typography
+       ========================================================================== */
+
+    h1,
+    h2,
+    h3,
+    h4,
+    h5,
+    h6 {
+        page-break-after: avoid;
+        page-break-inside: avoid;
+        font-weight: bold;
+    }
+
+    h1 {
+        font-size: 24pt;
+    }
+
+    h2 {
+        font-size: 18pt;
+    }
+
+    h3 {
+        font-size: 14pt;
+    }
+
+    p,
+    blockquote {
+        orphans: 3;
+        widows: 3;
+    }
+
+    /* ==========================================================================
+       Links
+       ========================================================================== */
+
+    a {
+        text-decoration: underline;
+        color: #000;
+    }
+
+    /* Show URLs after links for reference */
+    a[href^="http"]::after {
+        content: " (" attr(href) ")";
+        font-size: 10pt;
+        color: #666;
+    }
+
+    /* Don't show URLs for anchor links */
+    a[href^="#"]::after {
+        content: "";
+    }
+
+    /* ==========================================================================
+       Hide Interactive/Navigation Elements
+       ========================================================================== */
+
+    /* Hide site navigation */
+    .site-header,
+    .main-nav,
+    .nav-menu,
+    .hamburger,
+    .nav-overlay {
+        display: none !important;
+    }
+
+    /* Hide footer social icons and interactive elements */
+    .contact-icons,
+    .footer-nav {
+        display: none !important;
+    }
+
+    /* Hide any buttons or form elements */
+    button,
+    input,
+    textarea,
+    select {
+        display: none !important;
+    }
+
+    /* ==========================================================================
+       Content Sections
+       ========================================================================== */
+
+    /* Hero section adjustments */
+    .hero {
+        padding: 0 0 1cm;
+        border-bottom: 2px solid #000;
+        margin-bottom: 1cm;
+    }
+
+    .hero-title {
+        font-size: 28pt;
+        margin-bottom: 0.5cm;
+    }
+
+    .hero-subtitle {
+        font-size: 14pt;
+    }
+
+    /* Content sections */
+    .content-section {
+        page-break-inside: avoid;
+        margin-bottom: 1cm;
+    }
+
+    .section-title {
+        border-bottom: 1px solid #000;
+        padding-bottom: 0.2cm;
+        margin-bottom: 0.5cm;
+    }
+
+    /* ==========================================================================
+       Gallery Items
+       ========================================================================== */
+
+    .gallery {
+        display: block;
+    }
+
+    .gallery-grid {
+        display: block;
+    }
+
+    .gallery-item {
+        page-break-inside: avoid;
+        margin-bottom: 1cm;
+        border: 1px solid #ccc;
+        padding: 0.5cm;
+    }
+
+    .gallery-item img {
+        max-width: 100%;
+        height: auto;
+        display: block;
+        margin-bottom: 0.3cm;
+    }
+
+    .gallery-caption,
+    .painting-title,
+    .painting-info {
+        font-size: 11pt;
+        margin-bottom: 0.2cm;
+    }
+
+    /* ==========================================================================
+       Footer Content
+       ========================================================================== */
+
+    .site-footer {
+        page-break-before: avoid;
+        border-top: 2px solid #000;
+        padding-top: 0.5cm;
+        margin-top: 1cm;
+    }
+
+    .footer-content {
+        display: block;
+    }
+
+    .footer-contact,
+    .footer-info {
+        margin-bottom: 0.5cm;
+    }
+
+    .footer-contact h3 {
+        font-size: 14pt;
+        margin-bottom: 0.3cm;
+    }
+
+    .footer-contact p,
+    .footer-info p {
+        font-size: 11pt;
+        margin-bottom: 0.2cm;
+    }
+
+    /* Show contact information clearly */
+    .contact-name {
+        font-weight: bold;
+        font-size: 12pt;
+    }
+
+    /* Hide copyright and bottom nav in print */
+    .footer-bottom,
+    .copyright {
+        display: none !important;
+    }
+
+    /* ==========================================================================
+       Utility Classes
+       ========================================================================== */
+
+    /* Force page breaks */
+    .page-break-before {
+        page-break-before: always;
+    }
+
+    .page-break-after {
+        page-break-after: always;
+    }
+
+    .page-break-avoid {
+        page-break-inside: avoid;
+    }
+}

